async openLink(notification, wait) {
  const tab = notification.type === "donation_tab";
  const formattedURL = Services.urlFormatter.formatURL(notification.URL);

// Fall back to opening a browser window if we don't have a tabmail.
if (!tab || !tabmail) {
  lazy.openLinkExternally(formattedURL);
} else {
  tabmail.openTab("contentTab", {
    url: formattedURL,
    background: false,
    linkHandler: "single-page",
  });

add_task(async function test_formatted_url() {
  const testUrl = "https://example.com/%NAME%";
  const element = container.shadowRoot.querySelector("a");
  const formattedUrl = Services.urlFormatter.formatURL(testUrl);

  Assert.notEqual(
    formattedUrl,
    testUrl,
    "Formatted URL should be different from test value"
  );

  container.setAttribute("url", testUrl);

  Assert.equal(
    element.href,
    formattedUrl,
    "Should format URL before displaying"
  );
});
